mapper.select:
select cm.message_num ,cm.message_type_cd ,cm.message_text_ko ,cm.message_text_en ,cm.message_text_zh ,cm.message_text_ja ,cm.message_text_ot ,cm.remark ,cm.create_date ,cm.create_by ,cm.update_date ,cm.update_by from com_message cm where 1=1
and cm.message_num = #{MESSAGE_NUM}
and cm.message_type_cd = #{MESSAGE_TYPE_CD}
and cm.message_text_ko like '%' || #{MESSAGE_TEXT_KO} || '%'
order by cm.message_num

mapper.update:
update com_message cm
   set cm.message_type_cd	= upper(#{MESSAGE_TYPE_CD})
      ,cm.message_text_ko	= #{MESSAGE_TEXT_KO}
      ,cm.message_text_en	= #{MESSAGE_TEXT_EN}
      ,cm.message_text_zh	= #{MESSAGE_TEXT_ZH}
      ,cm.message_text_ja	= #{MESSAGE_TEXT_JA}
      ,cm.message_text_ot	= #{MESSAGE_TEXT_OT}
      ,cm.remark			= #{REMARK}
      ,cm.update_date		= sysdate
      ,cm.update_by			= #{UPDATE_BY}
 where 1=1
   and cm.code_type 		= upper(#{MESSAGE_NUM})

mapper.delete:
delete from com_message cm
 where 1=1
   and cm.message_num = #{MESSAGE_NUM}
